  Hypothesis NF : nf < n.
  Variable mu' : Z.
  Hypothesis MU' : rf_total c nf au <= mu' /\ mu <= mu' <= mu + kUserMapSize /\ hidden (mu' mod kUserMapSize = 0).
  Let nnew := (mu' - au) / csz.
